input.command:
cd /home/user/rork-app 2>/dev/null

OWNER_TOKEN=$(cat /tmp/owner_token.txt 2>/dev/null)

echo "=== 3. INDEPENDENCE STATUS ==="
curl -s https://api.ivxholding.com/api/ivx/independence-status \
  -H "Authorization: Bearer $OWNER_TOKEN" 2>/dev/null | python3 -c "
import sys,json
d=json.loads(sys.stdin.read())
print(f'ok: {d.get(\"ok\")}')
# Print all keys
for k in sorted(d.keys()):
    if k != 'ok':
        v = d[k]
        if isinstance(v, dict):
            print(f'  {k}:')
            for k2 in sorted(v.keys()):
                v2 = v[k2]
                if isinstance(v2, str) and len(v2) > 60:
                    v2 = v2[:60] + '...'
                print(f'    {k2}: {v2}')
        elif isinstance(v, str) and len(v) > 80:
            print(f'  {k}: {v[:80]}...')
        else:
            print(f'  {k}: {v}')
" 2>/dev/null

echo ""
echo "=== 4. OWNER-CONTROL-PROOF (Rork dependency check) ==="
curl -s https://api.ivxholding.com/api/ivx/owner-control-proof \
  -H "Authorization: Bearer $OWNER_TOKEN" 2>/dev/null | python3 -c "
import sys,json
d=json.loads(sys.stdin.read())
print(f'ok: {d.get(\"ok\")}')
for k in sorted(d.keys()):
    if k != 'ok':
        v = d[k]
        if isinstance(v, str) and len(v) > 80:
            print(f'  {k}: {v[:80]}...')
        elif not isinstance(v, (dict, list)):
            print(f'  {k}: {v}')
        elif isinstance(v, list):
            print(f'  {k}: [{len(v)} items]')
        elif isinstance(v, dict):
            print(f'  {k}: {{keys: {list(v.keys())[:5]}}}')
" 2>/dev/null

